<?php
namespace LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Requests;
use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class DestinationRequest extends FormRequest { public function authorize():bool{return $this->user()?->can('manage iapm destinations')??false;} public function rules():array{$id=$this->route('destination')?->id;
        // An SMS gateway authenticates with HTTP Basic, so a password is required
        // on create. A generic webhook may use Basic auth, a bearer token, or none.
        $passwordRequired=!$id&&$this->input('type')==='sms_gateway';
        return ['name'=>['required','string','max:255',Rule::unique('iapm_destinations')->ignore($id)],'type'=>['required',Rule::in(['sms_gateway','generic_webhook'])],'enabled'=>['boolean'],'url'=>['required','url:http,https','max:2048'],'username'=>['nullable','string','max:255'],'password'=>[$passwordRequired?'required':'nullable','string','max:4096'],'bearer_token'=>['nullable','string','max:4096'],'default_receiver'=>['nullable','string','max:128'],'mode'=>['required',Rule::in(['json','form'])],'connect_timeout'=>['required','integer','between:1,60'],'timeout'=>['required','integer','between:1,300'],'retry_count'=>['required','integer','between:0,10'],'retry_delay_ms'=>['required','integer','between:0,60000'],'verify_tls'=>['boolean'],'allow_private_networks'=>['boolean'],'headers_json'=>['nullable','json']];} protected function prepareForValidation():void{$this->merge(['enabled'=>$this->boolean('enabled'),'verify_tls'=>$this->boolean('verify_tls'),'allow_private_networks'=>$this->boolean('allow_private_networks')]);} }
